export const COW_COMMANDS=Object.freeze(/** @type {const} */(['enterCow','buyCowFeed','feedCows','waterCows','cleanCowBarn','cleanCowStand','cleanCowCan','inspectCow','milkCow','moveCowMilk','discardCowMilk','toggleCowCooler']));
/** @typedef {typeof COW_COMMANDS[number]} CowCommandType */
/** @param {string} type */
export const isCowCommand=type=>COW_COMMANDS.some(k=>k===type);
/** Strict revision-owned commands; getters, prototypes and extra resource fields reject. @param {unknown} value */
export function validateCowCommand(value){if(!value||typeof value!=='object'||Array.isArray(value)||Object.getPrototypeOf(value)!==Object.prototype)return 'invalidCowCommand';const c=/** @type {Record<string,unknown>} */(value);if(Reflect.ownKeys(c).length!==Object.keys(c).length||Object.values(Object.getOwnPropertyDescriptors(c)).some(d=>!Object.hasOwn(d,'value'))||typeof c.id!=='number'||!Number.isSafeInteger(c.id)||c.id<1||typeof c.type!=='string'||!isCowCommand(c.type))return 'invalidCowCommand';const milk=c.type==='milkCow',move=c.type==='moveCowMilk',lot=move||c.type==='discardCowMilk',animal=c.type==='inspectCow'||milk,keys=['id','type',...(animal?['cowId']:[]),...(lot?['cowLot']:[]),...(milk||move?['cowStorage']:[])];if(Object.keys(c).length!==keys.length||Object.keys(c).some(k=>!keys.includes(k)))return 'invalidCowCommand';if((milk||move)&&c.cowStorage!=='can'&&c.cowStorage!=='cooler')return 'invalidCowCommand';if(lot&&(typeof c.cowLot!=='string'||!/^cow\.milk\.[1-9][0-9]*$/.test(c.cowLot)))return 'invalidCowCommand';if(animal&&(typeof c.cowId!=='string'||!/^cow\.(starter\.[ab]|bought\.1)$/.test(c.cowId)))return 'invalidCowCommand';return '';}
